		{ id: "a", room: "R1", start: "2026-03-01T09:00:00Z", end: "2026-03-01T10:00:00Z" },
		{ id: "b", room: "R2", start: "2026-03-01T09:00:00Z", end: "2026-03-01T10:00:00Z" },
	];
	assert.deepEqual(findConflicts(bookings), []);
